mapper.select:
SELECT count(DISTINCT link_id)
FROM track_event
WHERE send_log_id = #{sendLogId}
  AND event_type = 'CLICK'
  AND occurred_at >= #{since}

mapper.update:
UPDATE track_event
SET bot_yn = 'Y', updated_at = now()
WHERE send_log_id = #{sendLogId}
  AND occurred_at >= #{since}
  AND bot_yn = 'N'

mapper.select:
SELECT EXISTS (
	SELECT 1
	FROM track_event e
	JOIN send_log s ON s.send_log_id = e.send_log_id
	WHERE e.send_log_id = #{sendLogId}
	  AND e.event_type = #{eventType}
	  AND e.bot_yn = 'N'
	  AND s.kind = 'CAMPAIGN'
)
